body:
I hit this exact gap on 2026-07-13 while supervising a long-running worker from a Codex API session.

The worker reached a decision point and the watcher preserved the wake correctly, but the supervisor had no active assistant turn and therefore could not initiate a new user-facing chat response. The event remained available until I manually polled the fleet during a later turn. In practice, the worker sat waiting even though detection and durable capture were working as intended.

That makes the architectural boundary especially clear: in-session wake injection cannot guarantee timely delivery on every harness. An out-of-band transport is needed independently of supervisor-turn liveness.

For a narrow first version, I would favor:

- actionable states only (`done`, `needs-decision`, `blocked`, `failed`);
- at-most-once delivery per event, with durable retry state;
- a generic webhook adapter plus local desktop notifications where supported;
- notifier failure always failing open and never delaying supervision;
- an end-to-end regression test proving that an event produced while the supervisor is idle results in exactly one external notification within a bounded interval.

Happy to help implement after maintainer direction on the preferred adapter and configuration surface.

ok, I've made it `flake.nix`

```nix
{
  description = "Firstmate — herdr + opencode runtime on Nix";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    flake-utils.url = "github:numtide/flake-utils";
  };

  outputs = { self, nixpkgs, flake-utils }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs { inherit system; };
        lib = pkgs.lib;

        # ----------------------------------------------------------------------
        # Pinned Herdr v0.7.4 (protocol 16 — CI pin, fm-install-herdr.sh)
        # ----------------------------------------------------------------------
        herdrVersion = "0.7.4";

        herdrAsset = {
          x86_64-linux = {
            asset = "herdr-linux-x86_64";
            hash = "sha256-vA/ALUulAPnKwjU6Q+Z/4DZ4Xsym61U3jgUPrDwQMFk=";
          };
          aarch64-linux = {
            asset = "herdr-linux-aarch64";
            hash = "sha256-VE4AAt5CgG0atkzN7zp+dBTyRxewtrAivJ5X0u79JqI=";
          };
          x86_64-darwin = {
            asset = "herdr-macos-x86_64";
            hash = "sha256-3fQwEzNS4XEkE9XYZbNKSFVG9GWIk/yJmGJX1lp1hag=";
          };
          aarch64-darwin = {
            asset = "herdr-macos-aarch64";
            hash = "sha256-JJkuFiXb3LGDVKWeKZ5LJjwxJACzE5bNwHzUbtV/JKc=";
          };
        }.${system};

        herdr-bin = pkgs.stdenv.mkDerivation {
          pname = "herdr";
          version = herdrVersion;
          src = pkgs.fetchurl {
            url = "https://github.com/ogulcancelik/herdr/releases/download/v${herdrVersion}/${herdrAsset.asset}";
            hash = herdrAsset.hash;
          };
          dontUnpack = true;
          installPhase = ''
            mkdir -p $out/bin
            cp $src $out/bin/herdr
            chmod +x $out/bin/herdr
          '';
          meta = {
            mainProgram = "herdr";
            description = "Agent-native terminal backend with per-pane agent state";
            homepage = "https://herdr.dev";
            license = lib.licenses.agpl3Only;
            platforms = lib.platforms.linux ++ lib.platforms.darwin;
          };
        };

        # ----------------------------------------------------------------------
        # Pinned Treehouse v2.0.1 (CI pin, fm-install-treehouse.sh)
        # ----------------------------------------------------------------------
        treehouseVersion = "2.0.1";

        treehouseAsset = {
          x86_64-linux = {
            archive = "treehouse-v${treehouseVersion}-linux-amd64.tar.gz";
            hash = "sha256-HVoydRq5IWcBA/0gHdsrkbRzOMsTl29FZCuCfPiXavI=";
          };
          aarch64-linux = {
            archive = "treehouse-v${treehouseVersion}-linux-arm64.tar.gz";
            hash = "sha256-6szJxbmBJd+L13QlWY7uzuZssDcdtOsc918NgTwY+rk=";
          };
          x86_64-darwin = {
            archive = "treehouse-v${treehouseVersion}-darwin-amd64.tar.gz";
            hash = "sha256-HPRFgKWDf5leHTu3T0+9MRK2QqzSBAYIfZc1qBBhEv0=";
          };
          aarch64-darwin = {
            archive = "treehouse-v${treehouseVersion}-darwin-arm64.tar.gz";
            hash = "sha256-fuUHjz0fM8ARllSHl/zmVAjkWdU1MLd9S6VuB0+hwaI=";
          };
        }.${system};

        treehouse-bin = pkgs.stdenv.mkDerivation {
          pname = "treehouse";
          version = treehouseVersion;
          src = pkgs.fetchurl {
            url = "https://github.com/kunchenguid/treehouse/releases/download/v${treehouseVersion}/${treehouseAsset.archive}";
            hash = treehouseAsset.hash;
          };
          dontUnpack = true;
          installPhase = ''
            mkdir -p $out/bin
            tar -xzf $src -C $out/bin treehouse
            chmod +x $out/bin/treehouse
          '';
          meta = {
            mainProgram = "treehouse";
            description = "Git worktree acquisition for agent task isolation";
            homepage = "https://github.com/kunchenguid/treehouse";
            license = lib.licenses.mit;
            platforms = lib.platforms.linux ++ lib.platforms.darwin;
          };
        };

        # ----------------------------------------------------------------------
        # Dev shell packages (everything except npm globals)
        # ----------------------------------------------------------------------
        shellPkgs = with pkgs; [
          nodejs
          jq
          python3
          git
          bashInteractive
          bash-completion
          gh
          curl
          gnutar
          perl
          shellcheck
          herdr-bin
          treehouse-bin
        ];

      in
      {
        packages = {
          inherit herdr-bin treehouse-bin;
        };

        devShells.default = pkgs.mkShell {
          name = "firstmate";
          packages = shellPkgs;

          shellHook = ''
            # Guard: host bash may lack `complete` builtin
            if ! type complete &>/dev/null 2>&1; then
              unset BASH_COMPLETION_VERSINFO 2>/dev/null || true
            fi

            # Workaround for #!/usr/bin/env shebangs (fails on NixOS)
            if ! [ -x /usr/bin/env ] && command -v env &>/dev/null; then
              if command -v sudo &>/dev/null; then
                sudo ln -sf "$(command -v env)" /usr/bin/env 2>/dev/null || true
              fi
            fi

            # Ensure ~/.local/bin is on PATH (npm globals land here)
            local_bin="$HOME/.local/bin"
            mkdir -p "$local_bin"
            case ":$PATH:" in
              *:"$local_bin":*) ;;
              *) export PATH="$local_bin:$PATH" ;;
            esac

            # Ensure npm prefix is writable (Nix store default is read-only)
            npm_prefix="$HOME/.npm-global"
            mkdir -p "$npm_prefix/bin"
            npm config set prefix "$npm_prefix" 2>/dev/null || true
            case ":$PATH:" in
              *:"$npm_prefix/bin":*) ;;
              *) export PATH="$npm_prefix/bin:$PATH" ;;
            esac

            # Install npm global tools on first use (lazy, cached by npm)
            npm_globals="\
              @opencode/opencode \
              no-mistakes \
              tasks-axi \
              quota-axi \
              lavish-axi \
              gh-axi \
              chrome-devtools-axi"

            missing=""
            for pkg in $npm_globals; do
              name="''${pkg#@*/}"
              name="''${name:-$pkg}"
              command -v "$name" >/dev/null 2>&1 || missing="$missing $pkg"
            done

            if [ -n "$missing" ]; then
              echo "  firstmate: installing npm tools:$missing"
              npm install -g $missing 2>&1 | tail -5
            fi

            # Status
            echo ""
            echo "  firstmate dev shell ready ($system)"
            for tool in opencode herdr treehouse gh node python3; do
              if ver=$(command -v "$tool" 2>/dev/null; "$tool" --version 2>/dev/null); then
                printf "  %-12s %s\n" "$tool:" "$ver"
              else
                printf "  %-12s NOT FOUND\n" "$tool:"
              fi
            done
            echo ""
            echo "  Launch: opencode"
            echo "  Select backend: echo herdr > config/backend"
          '';
        };
      });
}
```

